from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    """
    Input to this function is a string containing multiple groups of nested parentheses. Your goal is to
    separate those groups into separate strings and return the list of those.
    Separate groups are balanced (each open brace is properly closed) and not nested within each other
    Ignore any spaces in the input string.
    """

    def find_balance(parentheses: str):
        stack = []
        for char in parentheses:
            if char == '(':
                stack.append(char)
            elif char == ')':
                if stack and stack[-1] == '(':
                    stack.pop()
                else:
                    return None
        return stack if not stack else None

    balances = []
    current_balance = []
    for char in paren_string:
        if char == '(':
            current_balance.append(char)
        elif char == ')':
            if current_balance:
                balance = ''.join(reversed(current_balance))
                current_balance = []
                if balance:
                    balances.append(balance)
        if not current_balance and not balances:
            current_balance.append(char)

    if current_balance:
        balance = ''.join(reversed(current_balance))
        if balance:
            balances.append(balance)

    for balance in list(filter(None, balances)):
        balances[balances.index(balance)] = '(' + balance + ')'

    return balances
